import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.model_selection import StratifiedKFold
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check if any feature shows significant association with outcome
    sig_features = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue  # Skip derived features
        x = feats.x[:, i]
        y = feats.y
        t_stat, p_val = stats.ttest_ind(x[y==1], x[y==0])
        if p_val < 0.05:
            sig_features.append((fid, t_stat, p_val))

    # If no significant features, return empty design
    if not sig_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Sort by effect size (absolute t-statistic)
    sig_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # Check for near-duplicates using correlation
    keep_features = []
    correlations = {}
    for i, fid1 in enumerate(feats.ids):
        if feats.types[i] == 'derived':
            continue
        for j, fid2 in enumerate(feats.ids):
            if i >= j or feats.types[j] == 'derived':
                continue
            corr = np.corrcoef(feats.x[:, i], feats.x[:, j])[0, 1]
            if abs(corr) >= 0.6:
                correlations[(fid1, fid2)] = corr

    # Filter out near-duplicates
    used_ids = set()
    for fid, _, _ in sig_features:
        if fid in used_ids:
            continue
        # Check if this feature is correlated with any already selected feature
        is_duplicate = False
        for kept_fid in keep_features:
            if (fid, kept_fid) in correlations or (kept_fid, fid) in correlations:
                if abs(correlations.get((fid, kept_fid), correlations.get((kept_fid, fid), 0))) >= 0.6:
                    is_duplicate = True
                    break
        if not is_duplicate:
            keep_features.append(fid)
            used_ids.add(fid)

    # Use all significant features as columns
    columns = tuple(keep_features)

    # Simple weighted score: sum of standardized features
    weights = {fid: 1.0 for fid in columns}

    # Return design with no drivers since we don't have strong evidence of causation
    return Design(drivers=(), columns=columns, products=(), loadings=weights)

